// Output 1: chart (valid numbers only). Output 2: text widget.
// A null/non-finite value or fault:true means the probe failed. Silence for
// longer than TIMEOUT_MS means still2 has stopped publishing, so the last
// number on screen is no longer current.
const TIMEOUT_MS = 60000;

const prev = context.get("timer");
if (prev) clearTimeout(prev);

const v = msg.payload;
const faulted = msg.fault === true || typeof v !== "number" || !isFinite(v);
const seen = msg.timestamp
    ? String(msg.timestamp).substring(11, 19)
    : new Date().toTimeString().substring(0, 8);

context.set("timer", setTimeout(() => {
    context.set("timer", null);
    node.status({ fill: "red", shape: "ring", text: "no data since " + seen });
    node.send([null, { payload: "⚠ NO DATA since " + seen }]);
}, TIMEOUT_MS));

if (faulted) {
    node.status({ fill: "red", shape: "dot", text: "FAULT " + seen });
    return [null, { payload: "⚠ FAULT (probe)" }];
}
node.status({ fill: "green", shape: "dot", text: v.toFixed(2) + " @ " + seen });
return [msg, msg];

