const ok = msg.statusCode >= 200 && msg.statusCode < 300;
const path = String(msg.url || "").replace(/^https?:\/\/[^/]+/, "");
if (!ok) {
    const err = (msg.payload && msg.payload.error) ? msg.payload.error : String(msg.payload);
    return [null, { payload: "still2 " + path + ": " + err }];
}
if (/^\/pid(\/run|\/reset)?$/.test(path)) return [{ payload: msg.payload }, null];
return [null, null];

const out = new Array(9).fill(null);
const fail = (why) => {
    out[8] = { payload: "Power page: getadv failed (" + why + ")" };
    return out;
};
if (msg.error) return fail(msg.error);
if (msg.statusCode && msg.statusCode >= 400) return fail("HTTP " + msg.statusCode);
let j = msg.payload;
if (typeof j === "string") { try { j = JSON.parse(j); } catch (e) { return fail("bad JSON"); } }
if (!j || typeof j !== "object") return fail("empty response");

// out[0] stays null: "Requested" is only written by the setpower ack path.
out[1] = { payload: (j.setPower === undefined ? "-" : j.setPower + " W") };
out[2] = { payload: (j.setPowerMode === 1 ? "AUTO" : "MANUAL") };
out[3] = { payload: (j.maxPower === undefined ? "-" : j.maxPower + " W") };
out[4] = { payload: (j.temperature === undefined ? "-" : j.temperature) };
out[5] = { payload: (j.meterOnline ? "online" : "not detected") };
out[6] = { payload: (j.gridPower === undefined ? "-" : j.gridPower + " W") };
out[7] = { payload: new Date().toLocaleTimeString() };
return out;

const v = Math.round(Number(msg.payload));
if (!Number.isFinite(v)) return null;
const target = Math.max(0, Math.min(v, 2400));
msg.requested = target;
msg.url = "http://iampwr.mianos.com/api/setpower?x=" + target;
msg.method = "GET";
msg.headers = {};
return msg;

const out = [null, null];
if (msg.error || (msg.statusCode && msg.statusCode >= 400)) {
    out[0] = { payload: "send failed" };
    out[1] = { payload: "Set power to " + msg.requested + " W failed: " + (msg.error || ("HTTP " + msg.statusCode)) };
    return out;
}
out[0] = { payload: (msg.requested === undefined ? "-" : msg.requested + " W") };
out[1] = { payload: "Requested " + msg.requested + " W" };
return out;

// Reflux pump reports duty + mechanical rpm; enabled=false means commanded off.
if (msg.error) return { source: "speed", online: false, payload: "no reading" };
if (msg.statusCode && msg.statusCode >= 400) return { source: "speed", online: false, payload: "HTTP " + msg.statusCode };
let j = msg.payload;
if (typeof j === "string") { try { j = JSON.parse(j); } catch (e) { return { source: "speed", online: false, payload: "bad JSON" }; } }
if (!j || j.duty === undefined) return { source: "speed", online: false, payload: "no duty" };
const bits = [j.duty + "%"];
if (typeof j.rpm_mech === "number" && j.rpm_mech > 0) bits.push(j.rpm_mech + " rpm");
if (j.enabled === false) bits.push("disabled");
if (j.telem_fresh === false) bits.push("stale telem");
return { source: "speed", online: (j.enabled !== false && j.telem_fresh !== false), payload: bits.join(" · ") };

// Condenser pump reports duty (and PWM frequency) but no rpm.
if (msg.error) return { source: "speed", online: false, duty: null, payload: "no reading" };
if (msg.statusCode && msg.statusCode >= 400) return { source: "speed", online: false, duty: null, payload: "HTTP " + msg.statusCode };
let j = msg.payload;
if (typeof j === "string") { try { j = JSON.parse(j); } catch (e) { return { source: "speed", online: false, duty: null, payload: "bad JSON" }; } }
if (!j || j.duty === undefined) return { source: "speed", online: false, duty: null, payload: "no duty" };
return { source: "speed", online: true, duty: j.duty, payload: j.duty + "%" };

// One row per pump. Two sources feed this node:
//   source="ok"    -> the still2 health flag (reflux_ok / condenser_ok)
//   source="speed" -> the pump's own GET /pump reading, incl. msg.online
// Each call stores its half in flow context and re-renders the whole row, so
// the badge and the speed never drift into separate widgets.
const KEY_OK = "pump_ok_reflux";
const KEY_SPD = "pump_spd_reflux";
const KEY_LINK = "pump_link_reflux";

if (msg.source === "ok") {
    flow.set(KEY_OK, String(msg.payload).indexOf("Online") !== -1);
} else if (msg.source === "speed") {
    flow.set(KEY_SPD, String(msg.payload));
    flow.set(KEY_LINK, msg.online);
} else {
    return null;
}

const ok = flow.get(KEY_OK);
const spd = flow.get(KEY_SPD);
const link = flow.get(KEY_LINK);
const state = (ok === undefined || ok === null) ? link : ok;
const badge = (state === undefined || state === null) ? "⚪" : (state ? "🟢" : "🔴");
const text = (spd === undefined || spd === null || spd === "") ? "…" : spd;
return { payload: badge + " " + text, topic: "pump/reflux" };

