// Watches both temperature feeds. Runs on a 10s tick; keeps no timers, only
// numbers and strings in flow context, so nothing here can fail to persist.
// Warns once per stale episode and re-arms when data returns.
const TIMEOUT_MS = Number(env.get("STILL2_NO_DATA_MS")) || 300000;
const now = Date.now();
if (!flow.get("check_started")) flow.set("check_started", now);

function check(ch) {
    const at = flow.get("seen_at_" + ch);
    const warnKey = "warned_" + ch;
    const last = (at === undefined || at === null) ? flow.get("check_started") : at;
    const stale = (now - last) > TIMEOUT_MS;

    if (!stale) {
        if (flow.get(warnKey)) flow.set(warnKey, false);
        return null;
    }
    if (flow.get(warnKey)) return null;   // already warned for this episode
    flow.set(warnKey, true);
    const stamp = flow.get("seen_txt_" + ch) || new Date(last).toTimeString().substring(0, 8);
    return { payload: "⚠ NO DATA since " + stamp, topic: "temp/" + ch };
}

return [check("middle"), check("head")];

const running = !!(msg.payload && msg.payload.running);
msg.payload = running ? "🟢 RUNNING" : "🔴 STOPPED";
return msg;

const s = String(msg.payload || "");
const m = s.match(/(\d+)/);
if (!m) return null;
const w = parseInt(m[1], 10);
return { payload: w > 0 ? 2400 : 0 };

const T = Number(msg.payload);
if (typeof T !== "number" || !isFinite(T)) return null;
// Below the ethanol azeotrope the vapour hasn't started, so an ABV is meaningless.
if (T < 78) return [{ payload: 0, topic: "ABV %", timestamp: msg.timestamp }, { payload: "— not boiling" }];
// Ethanol/water vapour temp -> distillate ABV (v/v), approximate.
const table = [
  [78.2, 96], [80, 90], [82, 85], [84, 82], [86, 78],
  [88, 73], [90, 66], [92, 57], [94, 46], [96, 33], [98, 16], [100, 0]
];
let abv;
if (T <= table[0][0]) abv = table[0][1];
else if (T >= table[table.length - 1][0]) abv = table[table.length - 1][1];
else {
  abv = table[0][1];
  for (let i = 0; i < table.length - 1; i++) {
    const t0 = table[i][0], a0 = table[i][1];
    const t1 = table[i + 1][0], a1 = table[i + 1][1];
    if (T >= t0 && T <= t1) { abv = a0 + (a1 - a0) * (T - t0) / (t1 - t0); break; }
  }
}
const pct = Math.round(abv * 10) / 10;
return [
  { payload: pct, topic: "ABV %", timestamp: msg.timestamp },
  { payload: "≈ " + pct + " % ABV" }
];

const T = Number(msg.payload);
if (typeof T !== "number" || !isFinite(T)) return null;
const done = flow.get("strip_done") === true;
if (T >= 98.5 && !done) {
  flow.set("strip_done", true);
  return { payload: "Strip nearly done - vapour " + T.toFixed(1) + " °C (ABV <15%)" };
}
if (T < 96 && done) flow.set("strip_done", false);
return null;

const d = msg.duty;
if (d === null || d === undefined) return null;
const n = Number(d);
if (!isFinite(n)) return null;
return { payload: n };
